function commonBrowse(o){return o.storefront&&!o.q&&o.category==='All projects'&&o.technology==='All technologies'&&o.source==='all'&&o.sort==='popular'&&!o.exclude.length&&!Object.keys(o.ranks).length}
function browseFetch(options){const body=JSON.stringify(options),early=window.__earlyBrowse;window.__earlyBrowse=null;const send=()=>commonBrowse(options)?fetch('/api/editorial?action=storefront',{signal:AbortSignal.timeout(20000)}):fetch('/api/editorial?action=browse',{method:'POST',headers:{'Content-Type':'application/json'},body,signal:AbortSignal.timeout(20000)});return early&&early.body===body?early.request.catch(send):send()}
async function browsePage(append=false){if(state.view==='collection'||state.remote)return;const key=browseKey(),token=++browseToken;clearTimeout(browseTimer);browsePending=true;browseRequested=key;$('#load-more').disabled=true;$('#grid').setAttribute('aria-busy','true');$('#status').textContent=append?'Loading more projects…':'Searching the saved catalogue…';try{const options=browseOptions();if(append&&browseData?.nextCursor)options.cursor=browseData.nextCursor;const response=await browseFetch(options);const data=await response.json();if(response.ok)Q.setEvidenceTime(data.snapshots?.catalog);if(!response.ok)throw Object.assign(Error(data.error?.message||'Catalogue search is unavailable.'),{code:data.error?.code});if(token!==browseToken||key!==browseKey()||state.view==='collection'||state.remote)return;const old=append?browseData.items:[];shelfPending.clear();shelfErrors.clear();browseData={...data,items:[...old,...data.items],arranged:Object.fromEntries(Object.keys(data.shelves||{}).map(id=>[id,!data.publicPools]))};browseSignature=key;const all=new Map([...browseData.items,...data.shelfItems].map(r=>[r.full.toLowerCase(),r]));catalog=[...all.values()];for(const r of curated){const saved=all.get(r.full.toLowerCase());if(saved)Object.assign(r,saved)}if(data.editorial)editorial=data.editorial;discovered=[...catalog];visibleLimit=browseData.items.length;$('#status').textContent=data.editorialNotice||'';}catch(e){if(token!==browseToken)return;if(e.code==='catalog_changed'&&append){browseSignature='';browseRequested='';browsePending=false;return browsePage(false)}$('#status').textContent='Catalogue search is temporarily unavailable. Loaded projects are still available. '+e.message;$('#status').insertAdjacentHTML('beforeend',' <button type="button" id="retry-browse">Retry search</button>');$('#retry-browse').onclick=()=>{browseRequested='';void browsePage()};}finally{if(token===browseToken){browsePending=false;$('#grid').removeAttribute('aria-busy');render()}}}
