async function loadProject(full){if(detailCache.has(full))return detailCache.get(full);if(!detailPending.has(full))detailPending.set(full,(async()=>{const res=await fetch('/api/editorial?action=detail&id='+encodeURIComponent(full),{signal:AbortSignal.timeout(20000)});const data=await res.json();if(!res.ok)throw Error(data.error?.message||'Project details are temporarily unavailable.');detailCache.set(full,data.repo);detailCache.set(data.repo.full,data.repo);if(detailCache.size>100)detailCache.delete(detailCache.keys().next().value);return data.repo})().finally(()=>detailPending.delete(full)));return detailPending.get(full)}
