function cover(r){const preview=S.images(r)[0];return `${preview?`<img class="project-preview" src="${escape(preview.src)}"${previewAttributes(preview,'(max-width: 760px) 235px, 300px')} alt="${escape(r.name)} ${preview.kind==='demo'?'demo screenshot':'project image'}" loading="lazy" decoding="async">`:''}`+ `<div class="cover-inner"><span class="cover-logo">${escape(r.symbol||r.name.slice(0,1).toUpperCase())}</span><span class="cover-title">${escape(r.name)}</span></div><span class="cover-kicker">${escape(r.category)}</span>${tracked()[r.full]?`<span class="fork-badge">${P.isSpace(r)?'Tracked':tracked()[r.full].available===false?'Fork unavailable':'Fork verified'}</span>`:''}`}
