function likeButton(r){const selected=A.has(r.full);return `<button class="like-button ${selected?'liked':''}" data-like="${escape(r.full)}" aria-label="${selected?'Unlike':'Like'} ${escape(r.name)}" aria-pressed="${selected}" ${A.busy(r.full)?'disabled':''}><svg width="18" height="18" viewBox="0 0 24 24" fill="${selected?'currentColor':'none'}" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/></svg></button>`}
function savedProjects(){if(collectionMode==='recent')return [...J.items.values()].sort((a,b)=>Date.parse(b.viewedAt)-Date.parse(a.viewedAt)).map(row=>repoData(row.id)).filter(Boolean);const liked=[...A.liked].map(repoData).filter(Boolean),trackedProjects=Object.values(tracked()).map(x=>x.repo).filter(Boolean);return collectionMode==='likes'?liked:collectionMode==='forks'?trackedProjects:[...new Map([...liked,...trackedProjects].map(r=>[r.full,r])).values()]}
function card(r,shelf='all'){if(typeof shelf!=='string')shelf='all';const growth=P.isSpace(r)?null:S.trend(r);const action=P.action(r);return `<article class="card" data-shelf="${escape(shelf)}"><button class="cover" style="${coverStyle(r)}" data-details="${escape(r.full)}" aria-label="View ${escape(r.name)} details">${cover(r)}</button><div class="card-heading"><h3><button data-details="${escape(r.full)}">${escape(r.name)}</button></h3>${likeButton(r)}</div><p class="card-description">${escape(r.description)}</p><div class="tech-tags">${S.technologies(r).slice(0,3).map(t=>`<button data-tech="${escape(t)}">${escape(t)}</button>`).join('')}</div><div class="card-bottom">${P.isSpace(r)?`<span title="Hugging Face likes">♡ ${stars(r.likes)}</span>`:`<span title="GitHub stars">☆ ${stars(r.stars)}</span><span title="GitHub forks">⑂ ${stars(r.forks)}</span>`}${growth?.score>0?`<span class="growth" title="Growth over ${Math.round(growth.days)} days">+${stars(growth.stars)} stars</span>`:''}<button class="fork-button" data-details="${escape(r.full)}">Details</button></div><div class="card-actions">${Q.hasLiveDemo(r)&&D.isAvailable(r)?`<a data-analytics="demo_click" data-project="${escape(r.full)}" data-public-demo="true" href="${escape(safeUrl(r.demo))}" target="_blank" rel="noopener">Try demo ↗</a>`:`<span>${r.demo?'Demo unavailable':'No demo link'}</span>`}${D.isAvailable(r)?`${A.user?`<a class="card-fork" data-analytics="fork_click" data-project="${escape(r.full)}" data-github-fork="${!P.isSpace(r)}" href="${escape(protectedLink(action.url))}" target="_blank" rel="noopener" title="${escape(action.label)}">${escape(action.short)}</a>${P.isSpace(r)&&P.githubFull(r)?`<a data-analytics="fork_click" data-project="${escape(r.full)}" data-github-fork="true" href="${escape(protectedLink('https://github.com/'+P.githubFull(r)+'/fork'))}" target="_blank" rel="noopener">⑂ Fork</a>`:''}`:lockedAction(action.short,action.label)}`:`<button data-details="${escape(r.full)}">View tracking</button>`}</div></article>`}
function matching(repos,{category=state.category,query=true}={}){const words=state.query.toLowerCase().trim().split(/\s+/).filter(Boolean);return repos.filter(r=>(state.view==='collection'||state.remote&&A.user?.admin||Q.publishedEligible(r))&&(state.view==='collection'||!J.settings.hideSeen||!J.seen(r.full))&&P.matchesSource(r,state.provider)&&(state.view==='collection'||Q.hasLiveDemo(r))&&(category==='All projects'||E.matchesCategory(r,category))&&(state.technology==='All technologies'||S.technologies(r).includes(state.technology))&&(!query||r.externalQuery===state.query&&state.remote||words.every(q=>[r.full,r.name,r.description,r.language,...S.technologies(r),(r.topics||[]).join(' ')].some(t=>String(t||'').toLowerCase().includes(q)))))}
function order(repos,sort=$('#sort').value){if(sort==='reposhelf')return repos.filter(r=>r.repoShelfClicks>0).sort((a,b)=>b.repoShelfClicks-a.repoShelfClicks||a.full.localeCompare(b.full));if(['popular','featured','trending'].includes(sort))return sort==='trending'?S.sorted(repos.filter(r=>!P.isSpace(r)),'trending'):P.popular(repos);const list=[...repos];if(sort==='releases')return list.filter(r=>S.recentRelease(r)).sort((a,b)=>Date.parse(b.latestRelease.publishedAt)-Date.parse(a.latestRelease.publishedAt));if(sort==='stars')list.sort((a,b)=>(b.stars??-1)-(a.stars??-1));if(sort==='forks')list.sort((a,b)=>(b.forks??-1)-(a.forks??-1));if(sort==='newest')list.sort((a,b)=>new Date(b.created||0)-new Date(a.created||0));if(sort==='updated')list.sort((a,b)=>new Date(b.updated||0)-new Date(a.updated||0));if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));return list}
function ribbon(title,items,{category='All projects',rank='popular',caption='',controls=false,community=false,custom=false,sponsored=false,limit=12,shelf='all'}={}){return `<section class="ribbon" data-shelf="${escape(shelf)}"><div class="ribbon-heading"><div><h3>${escape(title)}</h3>${caption?`<p>${escape(caption)}</p>`:''}</div><div class="ribbon-options">${controls?`<button data-ribbon-rank="popular" data-ribbon-category="${escape(category)}" class="${rank==='popular'?'active':''}">Popular</button><button data-ribbon-rank="trending" data-ribbon-category="${escape(category)}" class="${rank==='trending'?'active':''}">Trending</button>`:''}${community||custom||sponsored?'':`<button class="view-all" data-view-all="${escape(category)}" data-rank="${rank}">View all</button>`}</div></div>${items.length?`<div class="ribbon-track">${items.slice(0,limit).map(community?communityCard:sponsored?sponsoredCard:card).join('')}</div>`:`<p class="ribbon-empty">${community?'No recent discussions match these filters yet.':rank==='trending'?'Measured trends will appear once we have at least a day of star and fork history.':'No projects match these filters yet.'}</p>`}</section>`}
function sponsoredCard(r){return card(r,'sponsored').replace('<article class="card" data-shelf="sponsored">','<article class="card sponsored-card" data-shelf="sponsored"><span class="sponsored-label">Sponsored · Test preview</span>')}
function sponsoredRibbon(){if(!A.user?.admin||!sponsored.length)return '';const list=matching(sponsored.map(r=>({...repoData(r.full),...r})));const offset=(sponsorOffset+Math.floor(Date.now()/60000))%Math.max(1,list.length),rotated=[...list.slice(offset),...list.slice(0,offset)];return ribbon('Sponsored',rotated,{sponsored:true,caption:'Administrator test preview. Separate from editorial selections; order rotates fairly.',limit:5})}
let sponsorPending=null,sponsorIdentity=null;async function loadSponsored(){const identity=A.user?.id||'visitor';if(sponsorPending&&sponsorIdentity===identity)return sponsorPending;sponsorIdentity=identity;return sponsorPending=(async()=>{try{const response=await fetch('/api/promotions?action=feed',{signal:AbortSignal.timeout(10000)});if(!response.ok)return;const data=await response.json();if((A.user?.id||'visitor')!==identity)return;const items=Array.isArray(data.items)?data.items.filter(r=>P.validId(r.full)&&typeof r.name==='string'&&D.demoUrl(r.demo)):[];await Promise.all(items.map(async r=>{const current=repoData(r.full);if(!current?.lastCheckedAt||!current?.demoHealth){try{await loadProject(r.full)}catch{}}}));if((A.user?.id||'visitor')!==identity)return;sponsored=items;render()}catch{}finally{if(sponsorIdentity===identity)sponsorPending=null}})()}
async function promoteOption(full){if(!A.user?.admin||!A.user?.githubConnected||P.isSpace(repoData(full)))return;const identity=A.user.id,key=identity+':'+full;try{let allowed=promotionEligibility.get(key);if(allowed===undefined){const result=await A.request('/api/promotions?action=eligibility&repo='+encodeURIComponent(full));allowed=result.eligible===true;promotionEligibility.set(key,allowed)}if(A.user?.id!==identity||!A.user?.admin||!allowed||!$('#detail').open||lastDetailId!==full)return;const slot=$('#promote-option');if(slot)slot.innerHTML=`<a class="button outline" href="/promotions.html?repo=${encodeURIComponent(full)}">Promote listing ↗</a>`}catch{}}
function rowItems(row,pool){if(!state.remote&&browseData?.shelves&&Object.hasOwn(browseData.shelves,row.id)){const items=browseData.shelves[row.id].map(repoData).filter(Boolean);if(browseData.arranged?.[row.id]!==false)return items;const n=browseData.publicShuffleCounts?.[row.id]??items.length;return [...E.arrange(items.slice(0,n),row,{seed:pageOrderSeed,manual:row.mode==='manual'}),...items.slice(n)];}let repos=row.mode==='manual'?row.items.map(repoData).filter(Boolean):pool;repos=matching(repos);if(['hero','picks'].includes(row.builtin_key))repos=repos.filter(r=>Q.featuredEligible(r,undefined,{lenient:row.mode==='manual'}));if(row.category)repos=repos.filter(r=>E.matchesCategory(r,row.category));if(['random','daily'].includes(row.mode))return E.shuffle(repos,{mode:row.mode,seed:pageOrderSeed,row:row.id});if(row.mode==='reposhelf')return repos.filter(r=>r.repoShelfClicks>0).sort((a,b)=>b.repoShelfClicks-a.repoShelfClicks||a.full.localeCompare(b.full));if(row.mode==='community')return C.rank(repos);if(row.mode==='releases')return P.popular(repos.filter(r=>S.recentRelease(r)));return E.arrange(row.mode==='manual'?repos:order(repos,row.mode),row,{seed:pageOrderSeed,manual:row.mode==='manual'})}
