function moveHero(step,{wrap=false}={}){const track=$('#hero-track'),slides=[...track.children];if(!slides.length)return;heroIndex=wrap?(heroIndex+step+slides.length)%slides.length:Math.max(0,Math.min(slides.length-1,heroIndex+step));const left=slides[heroIndex].offsetLeft-slides[0].offsetLeft;track.scrollTo({left,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
