const signinIcon=path=>`<svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${path}</svg>`;
function signinContent(){return `<p class="signin-intro">Sign in to keep your finds with you.</p><ul class="signin-benefits"><li><span class="signin-benefit-icon">${signinIcon('<rect x="3" y="4" width="18" height="16" rx="3"/><path d="m10 9 5 3-5 3Z"/>')}</span><div><strong>Pick up where you left off</strong><p>Choose to sync your viewing history across devices.</p></div></li><li><span class="signin-benefit-icon">${signinIcon('<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>')}</span><div><strong>Keep your favourites with you</strong><p>Save liked projects and find them on any device.</p></div></li><li><span class="signin-benefit-icon">${signinIcon('<circle cx="6" cy="5" r="2"/><circle cx="18" cy="5" r="2"/><circle cx="12" cy="19" r="2"/><path d="M6 7v3a6 6 0 0 0 6 6m6-9v3a6 6 0 0 1-6 6v1"/>')}</span><div><strong>Know what you’ve made your own</strong><p>Create forks on GitHub. Track your verified public forks across devices.</p></div></li><li><span class="signin-benefit-icon">${signinIcon('<path d="M8 3v4m8-4v4M6 7h12v4a6 6 0 0 1-6 6v4"/>')}</span><div><strong>Build with your AI assistant</strong><p>Create a personal key to use RepoShelf as a connector in Claude or Codex.</p></div></li></ul>${A.enabled?`<a class="button lime github-signin" href="/api/auth?action=start">${githubMark}<span>Sign in with GitHub</span><svg class="signin-arrow" viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg></a>${A.googleEnabled?`<a class="button outline google-signin" href="/api/auth?action=start&provider=google">${googleMark}<span>Continue with Google</span></a><p class="signin-note">GitHub also unlocks forks, repository submissions and reports. Google works for likes, collections and history. Use the same option each time, or connect both in Account &amp; data to keep one collection.</p>`:''}<p class="signin-legal">By signing in you agree to our <a href="/terms.html" target="_blank" rel="noopener">Terms of Service</a> and acknowledge our <a href="/privacy.html" target="_blank" rel="noopener">Privacy Policy</a>. See our <a href="/cookies.html" target="_blank" rel="noopener">Cookie Policy</a> for how cookies and storage are used.</p><p class="signin-security">Sign-in is handled by ${A.googleEnabled?'GitHub or Google':'GitHub'}.<br>RepoShelf never sees your password.</p>`:'<p class="signin-security">GitHub sign-in is being configured. You can continue browsing the catalog.</p>'}`}
function renderAccount(){const person=A.user;$('#account').dataset.mode=person?'account':'signin';$('#account-mode-label').textContent=person?'Your account':'Sign-In';$('#account-title').textContent=person?'Your profile':'Your next project starts here.';$('#account-title').classList.toggle('sr-only',Boolean(person));
const icon=kind=>signinIcon({link:'<path d="M10 14a4 4 0 0 0 5.7 0l3-3a4 4 0 0 0-5.7-5.7l-1 1M14 10a4 4 0 0 0-5.7 0l-3 3A4 4 0 0 0 11 18.7l1-1"/>',connector:'<path d="M8 3v4m8-4v4M6 7h12v4a6 6 0 0 1-6 6v4M9 7v4m6-4v4"/>',collection:'<path d="M6 3h12v18l-6-4-6 4Z"/>',submissions:'<rect x="4" y="4" width="16" height="16" rx="3"/><path d="M8 12h8m-4-4v8"/>',promotions:'<path d="m3 10 15-5v14L3 14Zm15-5 3-2v18l-3-2M6 15l2 6h4l-2-5"/>',privacy:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',admin:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="9" cy="6" r="2"/><circle cx="15" cy="12" r="2"/><circle cx="9" cy="18" r="2"/>',signout:'<path d="M9 4H4v16h5m4-4 4-4-4-4m-5 4h13"/>'}[kind]);
const row=(kind,label,attrs,badge='')=>`<${attrs.startsWith('href')?'a':'button'} class="profile-link" ${attrs}><span class="profile-link-icon">${icon(kind)}</span><span>${label}</span>${badge?'<small class="profile-test">'+badge+'</small>':''}<span class="profile-chevron" aria-hidden="true">›</span></${attrs.startsWith('href')?'a':'button'}>`;
$('#account-auth').innerHTML=person?`<div class="profile-identity"><span class="profile-avatar"><span>${escape(person.name.slice(0,1).toUpperCase())}</span>${/^https:\/\/avatars\.githubusercontent\.com\/u\/\d+\?s=96$/.test(person.avatarUrl||'')?`<img src="${escape(person.avatarUrl)}" alt="" referrerpolicy="no-referrer">`:''}</span><div><strong>${person.githubConnected?'@':''}${escape(person.name)}</strong><p>${person.githubConnected?'Signed in with GitHub':'Signed in with Google'}</p></div></div>${person.admin?'<span class="profile-role">Administrator</span>':''}<nav class="profile-navigation" aria-label="Profile"><section class="profile-group" aria-labelledby="profile-projects"><h3 id="profile-projects">Your projects</h3>${row('collection','My collection','type="button" id="profile-collection"')}${row('submissions','My submissions','href="/submissions.html"')}${person.admin?row('promotions','My promotions','href="/promotions.html"','Test'):''}</section><section class="profile-group" aria-labelledby="profile-preferences"><h3 id="profile-preferences">Account</h3>${row('privacy','Account & data','href="/account.html"')}${row('link','Linked accounts','href="/account.html#signin-methods"')}${row('connector','Connect your AI assistant','href="/connect.html"')}${row('signout','Sign out','type="button" id="signout"')}</section>${person.admin?`<section class="profile-group" aria-labelledby="profile-administration"><h3 id="profile-administration">Administration</h3>${row('admin','Admin dashboard','href="/admin.html"')}</section>`:''}</nav>`:signinContent();const avatar=$('.profile-avatar img');if(avatar)avatar.onerror=()=>avatar.remove();if($('#profile-collection'))$('#profile-collection').onclick=()=>{$('#account').close();openCollection()};if($('#signout'))$('#signout').onclick=async()=>{try{await A.signout();toast('Signed out. Your saved account collection is safe.')}catch(e){toast(e.message)}}}
let collectionBrowseFilters=null;
function openCollection(){if(state.view!=='collection'){collectionBrowseFilters={query:state.query,category:state.category,technology:state.technology,provider:state.provider,sort:$('#sort').value};A.track('page_view')}state.view='collection';collectionMode='all';visibleLimit=48;searchToken++;state.loading=false;state.query='';$('#search').value='';state.category='All projects';state.technology='All technologies';state.provider='all';$('#provider').value='all';$('#sort').value='popular';$('#status').textContent='';render();$('#section-heading').scrollIntoView({block:'start',behavior:'smooth'})}
function renderCollectionTools(){const panel=$('#collection-tools'),forks=state.view==='collection'&&collectionMode==='forks',importable=state.view==='collection'&&A.user&&A.guestCount;panel.hidden=!forks&&!importable;if(panel.hidden){panel.innerHTML='';return}panel.innerHTML=`${forks?`<div class="collection-fork-tools"><div><h3>Public forks</h3><p>${A.user?'Verified against your signed-in GitHub account. Private forks are not accessible.':'Sign in with GitHub to check and track your public forks.'}</p><p class="small">${A.forkSync.completedAt?'Last completed scan: '+escape(new Date(A.forkSync.completedAt).toLocaleString()):'Checks run in resumable batches. Saved public forks sync across devices.'}</p></div><button class="button lime" id="sync-forks" ${A.syncing?'disabled':''}>${A.user?A.syncing?'Checking forks…':A.forkSync.inProgress?'Continue checking forks':'Check my public forks':'Sign in with GitHub'}</button><p class="collection-fork-error" role="status">${escape(A.forkError||'')}</p></div>`:''}${importable?`<div class="collection-import"><p>Bring your ${A.guestCount} previously saved browser likes into your account.</p><button class="button outline" id="import-likes">Import browser likes</button></div>`:''}`;if($('#sync-forks'))$('#sync-forks').onclick=()=>A.user?void syncForks():openAccount();if($('#import-likes'))$('#import-likes').onclick=async e=>{e.target.disabled=true;try{await A.importGuest();toast('Browser likes imported into your account.')}catch(e){toast(e.message)}finally{render()}}}
function renderJourneyTools(){const panel=$('#journey-tools'),recent=state.view==='collection'&&collectionMode==='recent';panel.hidden=!recent;const hide=$('#hide-seen');hide.checked=J.settings.hideSeen===true;hide.disabled=!A.user||!J.ready||!J.available||!J.settings.rememberViews;hide.closest('.history-filter').hidden=state.view==='collection';if(!recent)return;panel.innerHTML=`<div><h3>Pick up where you left off</h3><p>Optionally remember projects you open, privately in your account. Your recently viewed list shows the last 90 days. History syncs across signed-in devices and is separate from analytics consent.</p>${!A.user?'<button class="button lime" data-history-signin>Sign in with GitHub</button>':`<label class="history-remember"><input id="remember-views" type="checkbox" ${J.settings.rememberViews?'checked':''} ${!J.ready||J.busy||!J.available?'disabled':''}>Remember viewed projects</label><button id="clear-history" class="button outline" ${J.busy||!J.items.size?'disabled':''}>Clear viewing history</button>`}<p class="small" role="status">${escape(J.error||(!J.ready?'Loading viewing history…':J.settings.rememberViews?'Your history is saved privately to your account.':'History is off. Turn it on to remember future projects.'))}</p></div>`;if($('#remember-views'))$('#remember-views').onchange=async e=>{try{await J.configure({rememberViews:e.target.checked,hideSeen:e.target.checked?J.settings.hideSeen:false})}catch(err){toast(err.message)}finally{render()}};if($('#clear-history'))$('#clear-history').onclick=async()=>{if(!confirm('Clear your viewing history across all signed-in devices? Your likes and forks are kept.'))return;try{await J.clear();toast('Viewing history cleared.')}catch(err){toast(err.message)}finally{render()}};const signin=panel.querySelector('[data-history-signin]');if(signin)signin.onclick=()=>openAccount()}
$('#hide-seen').onchange=async e=>{try{await J.configure({...J.settings,hideSeen:e.target.checked})}catch(err){toast(err.message)}finally{render()}};
window.addEventListener('reposhelf-journey',()=>render());
window.addEventListener('reposhelf-account',()=>{if(!A.user?.admin)sponsored=[];void loadSponsored();renderAccount();render();if($('#detail').open&&lastDetailId)showDetails(lastDetailId)});
function openAccount(){renderAccount();if(!$('#account').open)$('#account').showModal()}
$('#account-button').onclick=openAccount;
document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
document.addEventListener('click',e=>{const retryShelf=e.target.closest('[data-retry-shelf],[data-load-shelf-button]');if(retryShelf){void loadShelves([retryShelf.dataset.retryShelf||retryShelf.dataset.loadShelfButton]);return}const suggestion=e.target.closest('[data-search-suggestion]');if(suggestion){const item=browseData?.suggestions?.[Number(suggestion.dataset.searchSuggestion)];if(item){state.query=item.options.q;state.category=item.options.category||'All projects';state.technology=item.options.technology||'All technologies';state.provider=item.options.source;$('#search').value=state.query;$('#provider').value=state.provider;$('#sort').value=item.options.sort;useCatalog()}return}const share=e.target.closest('[data-share]');if(share){void shareListing(share.dataset.share);return}const like=e.target.closest('[data-like]');if(like){if(!A.user){openAccount();return}void A.toggle(like.dataset.like,repoData(like.dataset.like)).catch(err=>toast(err.message));return}if(e.target.closest('[data-open-recent]')){openCollection();collectionMode='recent';render();return}const mode=e.target.closest('[data-collection-mode]');if(mode){collectionMode=mode.dataset.collectionMode;render();return}const gated=e.target.closest('[data-requires-login]');if(gated&&!A.user?.githubConnected){e.preventDefault();openAccount();return}const analytic=e.target.closest('[data-analytics]');if(analytic&&analytic.dataset.analytics==='fork_click'&&analytic.dataset.githubFork==='true'&&!A.user){e.preventDefault();openAccount();return}if(analytic)A.track(analytic.dataset.analytics,analytic.dataset.project,analytic.closest('.ribbon')?.dataset.shelf||analytic.closest('[data-shelf]')?.dataset.shelf);if($('#more-filters').open&&!e.target.closest('#more-filters'))$('#more-filters').open=false;const heroStep=e.target.closest('[data-hero-step]');if(heroStep)moveHero(Number(heroStep.dataset.heroStep));const details=e.target.closest('[data-details]');if(details){detailImage=0;showDetails(details.dataset.details,false,details.closest('.ribbon')?.dataset.shelf||details.closest('[data-shelf]')?.dataset.shelf)}const tech=e.target.closest('[data-tech]');if(tech){state.technology=tech.dataset.tech;$('#detail').close();if(state.source==='github')useCatalog();else render()}const rank=e.target.closest('[data-ribbon-rank]');if(rank){ribbonModes[rank.dataset.ribbonCategory]=rank.dataset.ribbonRank;render()}const all=e.target.closest('[data-view-all]');if(all){state.source='github';state.category=all.dataset.viewAll;$('#sort').value=all.dataset.rank;useCatalog()}const gallery=e.target.closest('[data-gallery]');if(gallery){detailImage=Number(gallery.dataset.gallery);showDetails(gallery.dataset.repo)}const cat=e.target.closest('[data-category]');if(cat){const fromPanel=Boolean(cat.closest('.cat-panel'));state.category=cat.dataset.category;toggleCategoryPanel(false);if(state.source==='github'&&state.view==='discover')useCatalog();else render();if(fromPanel)focusCategory(state.category)}const nav=e.target.closest('[data-view]');if(nav){if(nav.dataset.view==='collection'){openCollection();return}if(state.view==='collection'&&collectionBrowseFilters){const prior=collectionBrowseFilters;for(const key of ['query','category','technology','provider'])state[key]=prior[key];$('#search').value=prior.query;$('#provider').value=prior.provider;$('#sort').value=prior.sort;collectionBrowseFilters=null}if(state.view!==nav.dataset.view)A.track('page_view');state.view=nav.dataset.view;if(state.view==='collection'){searchToken++;state.loading=false}$('#status').textContent='';render()}if(e.target.closest('#reset-filters')){state.category='All projects';state.technology='All technologies';state.provider='all';$('#provider').value='all';state.query='';$('#search').value='';render();if(state.source==='github'&&state.view==='discover')useCatalog()}});

$('#curated').onclick=()=>{state.remote=false;session=null;state.source='curated';state.query='';$('#search').value='';visibleLimit=48;searchToken++;state.loading=false;$('#status').textContent='';render()};$('#github').onclick=()=>{state.source='github';useCatalog()};
$('#search').oninput=e=>{clearTimeout(timer);if(e.target.value.trim())timer=setTimeout(()=>A.track('search',undefined,undefined,state.query),700);state.query=e.target.value;if(!searchSortChosen)$('#sort').value=state.query.trim()?'relevance':'popular';if(state.query)state.source='github';useCatalog()};
$('#provider').onchange=e=>{state.provider=e.target.value;useCatalog()};$('#clear-source').onclick=()=>{state.provider='all';$('#provider').value='all';useCatalog()};$('#sort').onchange=()=>{searchSortChosen=true;if(state.view==='discover')state.source='github';useCatalog()};$('#load-more').onclick=()=>{if(state.view==='discover'&&!state.remote&&browseData?.nextCursor){void browsePage(true);return}visibleLimit+=48;render()};$('#search-external').onclick=()=>discover(Boolean(state.remote&&hasMore()));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#more-filters').open){$('#more-filters').open=false;$('#more-filters summary').focus()}if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('#search').focus()}});
$('#hero-track').onscroll=()=>{const track=$('#hero-track');if(track.children.length<2)return;const stride=track.children[1].offsetLeft-track.children[0].offsetLeft;heroIndex=Math.min(track.children.length-1,Math.max(0,Math.round(track.scrollLeft/stride)))};$('#hero-track').onkeydown=e=>{if(e.target===$('#hero-track')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();moveHero(e.key==='ArrowRight'?1:-1)}};
setupHeroRotation();render();const catalogReady=loadCatalog();catalogReady.then(hideBootLoader,hideBootLoader);setTimeout(hideBootLoader,4000);catalogReady.then(async()=>{const requested=new URL(location.href).searchParams.get("project");if(requested){let repo=repoData(requested);if(!repo){try{repo=await loadProject(requested)}catch{}}if(repo){showDetails(repo.full)}else toast("This listing is being published. Please refresh in a few minutes.")}});loadSponsored();setInterval(()=>{if(!document.hidden&&A.user?.admin&&!document.activeElement?.closest('#ribbons'))void loadSponsored()},60000);if(new URL(location.href).searchParams.get('signin')==='failed'){toast('GitHub sign-in could not be completed. Please try again.');history.replaceState(null,'','/')}

document.addEventListener('error',e=>{if(e.target.matches?.('.project-preview, .hero-visual img'))e.target.remove();else if(e.target.matches?.('.detail-preview')){e.target.hidden=true;toast('This preview image is temporarily unavailable.')}},true);
